// GENERATED by scripts/sync-shared.mjs from app/src/terminal/risk.ts. Do not edit here.
// PRD P9.2 — risk badges from Jupiter audit data. No third-party risk API needed for v1.
import type { TerminalToken } from './types.js'

export type Tone = 'good' | 'warn' | 'bad' | 'muted'
export interface Badge { key: string; icon: string; label: string; tone: Tone; tip: string }

export const TOP_HOLDER_WARN = 30 // %
export const DEV_BALANCE_WARN = 10 // %
export const DEV_MINTS_WARN = 20

export function riskBadges(t: Pick<TerminalToken, 'audit' | 'isVerified'>): Badge[] {
  const a = t.audit
  if (!a) return [{ key: 'unaudited', icon: '?', label: 'Unaudited', tone: 'muted', tip: 'No audit data for this token yet.' }]
  const out: Badge[] = []
  out.push(a.mintAuthorityDisabled
    ? { key: 'mint', icon: '🔒', label: 'Mint revoked', tone: 'good', tip: 'Nobody can mint more supply.' }
    : { key: 'mint', icon: '🖨️', label: 'Mintable', tone: 'bad', tip: 'The creator can still mint new supply.' })
  out.push(a.freezeAuthorityDisabled
    ? { key: 'freeze', icon: '🧊', label: 'Freeze revoked', tone: 'good', tip: 'Token accounts cannot be frozen.' }
    : { key: 'freeze', icon: '❄️', label: 'Freezable', tone: 'bad', tip: 'The creator can freeze your tokens.' })
  if (a.topHoldersPercentage !== undefined && a.topHoldersPercentage > TOP_HOLDER_WARN) {
    out.push({ key: 'top', icon: '⚠', label: `Top holders ${a.topHoldersPercentage.toFixed(0)}%`, tone: 'warn', tip: 'A few wallets hold a large share of the supply.' })
  }
  if (a.devBalancePercentage !== undefined && a.devBalancePercentage > DEV_BALANCE_WARN) {
    out.push({ key: 'dev', icon: '🧑‍💻', label: `Dev holds ${a.devBalancePercentage.toFixed(0)}%`, tone: 'warn', tip: 'The deployer wallet still holds a large share.' })
  }
  if (a.devMints !== undefined && a.devMints > DEV_MINTS_WARN) {
    out.push({ key: 'serial', icon: '🔁', label: `Dev launched ${a.devMints.toLocaleString()} tokens`, tone: 'bad', tip: 'This deployer has launched many tokens before.' })
  }
  if (t.isVerified) out.push({ key: 'verified', icon: '✓', label: 'Verified', tone: 'good', tip: 'On Jupiter\'s verified list.' })
  return out
}

/** 0 (safe) … 3 (danger) summary used for row colouring. */
export function riskLevel(badges: Badge[]): number {
  const bad = badges.filter((b) => b.tone === 'bad').length
  const warn = badges.filter((b) => b.tone === 'warn').length
  if (badges.some((b) => b.key === 'unaudited')) return 1
  return Math.min(3, bad * 2 + warn)
}
